function validate([s, a, b, k]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 100000) return 's needs 1 to 100000 characters.';
  if (typeof a !== 'string' || a.length < 1 || a.length > 10) return 'a needs 1 to 10 characters.';
  if (typeof b !== 'string' || b.length < 1 || b.length > 10) return 'b needs 1 to 10 characters.';
  if (![s, a, b].every(t => /^[a-z]+$/.test(t))) return 's, a and b use only lowercase letters.';
  if (!Number.isInteger(k) || k < 1 || k > s.length) return 'k is between 1 and s.length.';
  return null;
}

