function beautifulIndices(s, a, b, k) {
  const findMatches = (pattern) => {
    const fail = new Array(pattern.length).fill(0);
    let length = 0;
    for (let i = 1; i < pattern.length; i++) {
      while (length > 0 && pattern[i] !== pattern[length]) length = fail[length - 1];
      if (pattern[i] === pattern[length]) length++;
      fail[i] = length;
    }
    const starts = [];
    length = 0;
    for (let i = 0; i < s.length; i++) {
      while (length > 0 && s[i] !== pattern[length]) length = fail[length - 1];
      if (s[i] === pattern[length]) length++;
      if (length === pattern.length) {
        starts.push(i - length + 1);
        length = fail[length - 1];
      }
    }
    return starts;
  };

  const matchesA = findMatches(a);
  const matchesB = findMatches(b);
  const result = [];
  let j = 0;
  for (const i of matchesA) {
    while (j < matchesB.length && matchesB[j] < i - k) {
      j++;
    }
    if (j < matchesB.length && matchesB[j] <= i + k) {
      result.push(i);
    }
  }
  return result;
}

