function beautifulIndices(s, a, b, k) {
  const out = [];
  for (let i = 0; i + a.length <= s.length; i++) {
    if (s.slice(i, i + a.length) !== a) continue;
    let found = false;
    for (let j = Math.max(0, i - k); j <= i + k && j + b.length <= s.length; j++) {
      if (s.slice(j, j + b.length) === b) { found = true; break; }
    }
    if (found) out.push(i);
  }
  return out;
}

