function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const sigma = size === 'large' ? int(2, 3) : int(1, 3);
  const word = (len) => Array.from({ length: len }, () => letters[int(0, sigma - 1)]).join('');
  const n = size === 'large' ? int(8000, 10000) : int(1, 14);
  const s = word(n);
  const maxLen = size === 'large' ? 10 : 4;
  const pick = () => {
    const len = int(1, maxLen);
    if (rand() < 0.7 && len <= n) { const start = int(0, n - len); return s.slice(start, start + len); }
    return word(len);
  };
  const a = pick();
  const b = rand() < 0.15 ? a : pick();
  const k = rand() < 0.5 ? int(1, Math.min(n, size === 'large' ? 60 : 4)) : int(1, n);
  return [s, a, b, k];
}
